// Purpose: ROW-021, ROW-142 and ROW-133 (REQ-010, REQ-011) — the suggestions the check offers for a
// flagged word, at the check endpoint: the expected correction of a one-letter or accent error comes
// first; the intended word of a sound-alike confusion is among the 5; and no suggestion is flagged
// when chosen, or is an offensive word.
// Provenance: generated by tests/invariants/suggestions-population.ts from dictionary-es 4.0.0 (the
// SHA-256-pinned oracle, D-029) with a fresh seed per run; the offensive list is this pass's own,
// written from general knowledge of Spanish; expected corrections and positions are the test's own
// record, never the product's answer.
//
// Test argument
// ROW-021 promise: for a one-letter or accent error the expected correction is the FIRST suggestion
//   (REQ-010 fail-if "the expected correction of a one-letter or accent error (for example gestión
//   for gestion) is not the first suggestion"; A-018 "suggestions are listed most likely first").
// ROW-021 wrong product: suggestions listed alphabetically, or in the dictionary's order, or by a
//   frequency table that puts "gestiona" before "gestión" — the right word is in the list, not first.
// ROW-021 given: 12 generated misspellings (8 one-letter edits — substitution, insertion, deletion,
//   transposition — and 4 accent errors) whose only dictionary word one edit away is the word they
//   were made from (so that word is the expected correction by the dictionary alone), plus the row's
//   own example gestion → gestión; when: one check of a text holding them all; then: each misspelling
//   is flagged at its own place and its first suggestion is exactly its expected correction.
// ROW-021 controls: the same kind of sample with the expected correction merely somewhere in the list
//   — passes on a product whose ranking is wrong, so it shows the flags and suggestions are reached
//   and only the order separates the target.
// ROW-021 technique: a property over generated inputs with one named example (gestion), the oracle's
//   one-edit neighbourhood making the expected value independent of the product.
// cases: ROW-021 target=ROW-021-the-expected-correction-of-a-one-letter-or-accent-error-is-the-first-suggestion control=ROW-021-control-the-expected-correction-is-among-the-suggestions
//
// ROW-142 promise: for sound-alike confusions (b/v, ll/y, s/c/z, a dropped h, g/j) the intended word
//   is among the 5 suggestions (REQ-010 "most likely first", up to 5; origin: domain).
// ROW-142 wrong product: suggestions by one-letter edit distance only — for "cayeja" it offers
//   one-letter neighbours and never "calleja", two letters away; or a product that knows b/v but
//   not a dropped h ("inóspito" → nothing useful).
// ROW-142 given: 3 generated misspellings of each class, each one sound-alike swap from a dictionary
//   word, with at most 5 dictionary words within one edit or one swap (so the intended word has room
//   among 5 by the dictionary alone); when: one check of a text holding all 15; then: each is flagged
//   at its place and its intended word is among its first 5 suggestions.
// ROW-142 controls: every sample misspelling is flagged at its own place — the check reaches each
//   word; untouched by a weak suggester.
// ROW-142 technique: a generated sample per confusion class (every class reached every run), the
//   expected word known from the generation, never from the product.
// cases: ROW-142 target=ROW-142-the-intended-word-of-a-sound-alike-confusion-is-among-the-5-suggestions control=ROW-142-control-every-sound-alike-misspelling-is-flagged-at-its-place
//
// ROW-133 promise: every suggestion offered, once chosen, is not flagged on the next check, and no
//   suggestion is a word from an independent list of Spanish vulgar or offensive words, over a
//   generated sample of misspellings (origin: domain; REQ-010, REQ-011).
// ROW-133 wrong product: suggestions straight from the dictionary's suggester — it offers "polla"
//   for "pílla" and "guió" (which REQ-008 tells the checker to flag) for "guío", and the writer's
//   chosen correction is flagged again on the next press.
// ROW-133 given: 8 generated one-letter errors plus 5 generated misspellings each one letter from a
//   dictionary word on the offensive list (a dictionary-only suggester would offer it); when: one check
//   of a text holding them, then one check of a text made of every suggestion offered for them, as
//   the writer would have chosen it; then: no suggestion for any flagged word is on the list, and the
//   second check flags nothing (the whole list empty).
// ROW-133 controls: the sample is flagged at its places and at least one suggestion is offered — the
//   second check is not vacuous; untouched by an offensive or self-flagging suggestion.
// ROW-133 technique: a generated sample salted with the harmful case (near-offensive misspellings),
//   an independent list as the oracle, and a relation between two checks (chosen → not flagged).
// cases: ROW-133 target=ROW-133-no-suggestion-is-offensive-and-every-chosen-suggestion-passes-the-next-check control=ROW-133-control-the-sample-is-flagged-and-suggestions-are-offered

import { expect, test } from '@playwright/test';
import { asActor, checkText, compose, fillerWords, freshRandom, type CheckAnswer, type Flag, type Placed } from './harness';
import {
  crowdedErrors,
  isOffensive,
  nearOffensiveErrors,
  soundAlikeErrors,
  uniqueCorrectionErrors,
  type Misspelling,
} from './suggestions-population';

type Rng = ReturnType<typeof freshRandom>;

/** A text holding every misspelling, each after one filler word, comma-separated; positions recorded. */
function textOf(rng: Rng, words: readonly string[]): { text: string; placed: Placed[] } {
  const fillers = fillerWords();
  const tokens: string[] = ['buscamos'];
  const seps: string[] = [];
  for (const w of words) {
    seps.push(tokens.length === 1 ? ' ' : ', ');
    tokens.push(rng.pick(fillers));
    seps.push(' ');
    tokens.push(w);
  }
  return compose(tokens, seps);
}

/** The flag standing exactly at `p` (same start, end and word), or undefined. */
const flagAt = (a: CheckAnswer, p: Placed): Flag | undefined =>
  a.flagged.find((f) => f.start === p.start && f.end === p.end && f.word === p.word);

function placedOf(placed: Placed[], sample: readonly Misspelling[]): { m: Misspelling; p: Placed }[] {
  const wrongs = new Set(sample.map((m) => m.wrong));
  const out = placed.filter((p) => wrongs.has(p.word)).map((p) => ({ m: sample.find((m) => m.wrong === p.word)!, p }));
  if (out.length !== sample.length) throw new Error(`setup: ${out.length} of ${sample.length} misspellings placed once each`);
  return out;
}

const GESTION: Misspelling = { intended: 'gestión', wrong: 'gestion', kind: 'accent' };

function rankingSample(rng: Rng): Misspelling[] {
  const oneLetter = uniqueCorrectionErrors(rng, 8, ['substitution', 'insertion', 'deletion', 'transposition']);
  const accent = uniqueCorrectionErrors(rng, 4, ['accent']).filter((m) => !oneLetter.some((o) => o.intended === m.intended));
  return [...oneLetter, ...accent].filter((m) => m.wrong !== GESTION.wrong && m.intended !== GESTION.intended).concat(GESTION);
}

test('ROW-021-the-expected-correction-of-a-one-letter-or-accent-error-is-the-first-suggestion', async () => {
  asActor('anonymous');
  const rng = freshRandom();
  const sample = rankingSample(rng);
  const { text, placed } = textOf(rng, rng.shuffle(sample.map((m) => m.wrong)));
  const where = placedOf(placed, sample);

  const answer = await checkText(text);
  const wrong = where
    .map(({ m, p }) => ({ m, f: flagAt(answer, p) }))
    .filter(({ m, f }) => !f || f.suggestions[0] !== m.intended)
    .map(({ m, f }) => `${m.wrong} (${m.kind}) → expected first "${m.intended}", got ${f ? JSON.stringify(f.suggestions) : 'no flag at its place'}`);
  expect(wrong, `ROW-021: each one-letter or accent error's expected correction is its FIRST suggestion, in ${JSON.stringify(text)} (seed ${rng.seed})`).toEqual([]);
});

test('ROW-021-control-the-expected-correction-is-among-the-suggestions', async () => {
  asActor('anonymous');
  const rng = freshRandom();
  const sample = rankingSample(rng);
  const { text, placed } = textOf(rng, rng.shuffle(sample.map((m) => m.wrong)));
  const where = placedOf(placed, sample);

  const answer = await checkText(text);
  const missing = where
    .map(({ m, p }) => ({ m, f: flagAt(answer, p) }))
    .filter(({ m, f }) => !f || !f.suggestions.includes(m.intended))
    .map(({ m, f }) => `${m.wrong} → "${m.intended}" not offered (${f ? JSON.stringify(f.suggestions) : 'no flag at its place'})`);
  expect(missing, `ROW-021 control: each misspelling is flagged at its place with its expected correction among the suggestions (seed ${rng.seed})`).toEqual([]);
});

test('ROW-142-the-intended-word-of-a-sound-alike-confusion-is-among-the-5-suggestions', async () => {
  asActor('anonymous');
  const rng = freshRandom();
  const sample = soundAlikeErrors(rng, 3);
  const { text, placed } = textOf(rng, rng.shuffle(sample.map((m) => m.wrong)));
  const where = placedOf(placed, sample);

  const answer = await checkText(text);
  const missing = where
    .map(({ m, p }) => ({ m, f: flagAt(answer, p) }))
    .filter(({ m, f }) => !f || !f.suggestions.slice(0, 5).includes(m.intended))
    .map(({ m, f }) => `${m.wrong} (${m.kind}) → "${m.intended}" not among the first 5 (${f ? JSON.stringify(f.suggestions) : 'no flag at its place'})`);
  expect(missing, `ROW-142: each sound-alike confusion's intended word is among its 5 suggestions, in ${JSON.stringify(text)} (seed ${rng.seed})`).toEqual([]);
});

test('ROW-142-control-every-sound-alike-misspelling-is-flagged-at-its-place', async () => {
  asActor('anonymous');
  const rng = freshRandom();
  const sample = soundAlikeErrors(rng, 3);
  const { text, placed } = textOf(rng, rng.shuffle(sample.map((m) => m.wrong)));
  const where = placedOf(placed, sample);

  const answer = await checkText(text);
  const unflagged = where.filter(({ p }) => !flagAt(answer, p)).map(({ m }) => `${m.wrong} (${m.kind})`);
  expect(unflagged, `ROW-142 control: every sound-alike misspelling is flagged at its own place (seed ${rng.seed})`).toEqual([]);
});

function offensiveSample(rng: Rng): Misspelling[] {
  const near = nearOffensiveErrors(rng, 5);
  const plain = crowdedErrors(rng, 8, 2).filter((m) => !near.some((n) => n.wrong === m.wrong));
  return [...plain, ...near];
}

test('ROW-133-no-suggestion-is-offensive-and-every-chosen-suggestion-passes-the-next-check', async () => {
  asActor('anonymous');
  const rng = freshRandom();
  const sample = offensiveSample(rng);
  const { text, placed } = textOf(rng, rng.shuffle(sample.map((m) => m.wrong)));
  const where = placedOf(placed, sample);

  const first = await checkText(text);
  const offered = first.flagged.flatMap((f) => f.suggestions.map((s) => ({ word: f.word, s })));
  const offensive = offered.filter(({ s }) => isOffensive(s)).map(({ word, s }) => `${word} → "${s}"`);
  expect(offensive, `ROW-133: no suggestion for any flagged word is on the offensive list, in ${JSON.stringify(text)} (seed ${rng.seed})`).toEqual([]);

  const chosen = [...new Set(where.flatMap(({ p }) => flagAt(first, p)?.suggestions ?? []))];
  expect(chosen.length, `ROW-133: the sample's flagged words are offered suggestions to choose (seed ${rng.seed})`).toBeGreaterThan(0);
  const again = textOf(rng, chosen);
  const second = await checkText(again.text);
  expect(
    second.flagged.map((f) => `${f.word} @${f.start}`),
    `ROW-133: every suggestion offered, once in the text as chosen, is not flagged on the next check — ${JSON.stringify(again.text)} (seed ${rng.seed})`,
  ).toEqual([]);
});

test('ROW-133-control-the-sample-is-flagged-and-suggestions-are-offered', async () => {
  asActor('anonymous');
  const rng = freshRandom();
  const sample = offensiveSample(rng);
  const { text, placed } = textOf(rng, rng.shuffle(sample.map((m) => m.wrong)));
  const where = placedOf(placed, sample);

  const answer = await checkText(text);
  const unflagged = where.filter(({ p }) => !flagAt(answer, p)).map(({ m }) => m.wrong);
  expect(unflagged, `ROW-133 control: every sample misspelling is flagged at its own place (seed ${rng.seed})`).toEqual([]);
  const total = where.reduce((n, { p }) => n + (flagAt(answer, p)?.suggestions.length ?? 0), 0);
  expect(total, `ROW-133 control: the sample is offered at least one suggestion (seed ${rng.seed})`).toBeGreaterThan(0);
});
